65	        let mut args = std::env::args();
66	        let _ = args.next();
67	        let file = match args.next() {
68	            Some(file) => file,
69	            None => std::process::exit(1),
70	        };
71	        let argv = args.collect::<Vec<_>>();
72	
73	        let runtime = match tokio::runtime::Builder::new_current_thread()
74	            .enable_all()
75	            .build()
76	        {
77	            Ok(runtime) => runtime,
78	            Err(_) => std::process::exit(1),
