45	pub(crate) async fn exec_server() -> anyhow::Result<ExecServerHarness> {
46	    let binary = cargo_bin("codex")?;
47	    let codex_home = TempDir::new()?;
48	    let mut child = Command::new(binary);
49	    child.args(["exec-server", "--listen", "ws://127.0.0.1:0"]);
50	    child.stdin(Stdio::null());
51	    child.stdout(Stdio::piped());
52	    child.stderr(Stdio::inherit());
