//!
//! Codex deploys as a single executable that dispatches to several distinct
//! CLIs using the "arg0 trick" (see [`codex_arg0`]). Test binaries that need to
//! exercise those helper CLIs must perform the same dispatch setup very early
//! in process startup, before any threads are spawned. This crate centralizes
//! that logic so individual test binaries only have to describe *when* to
//! dispatch, install aliases, or do nothing.
//!
//! The intended entry point is [`configure_test_binary_dispatch`], called from
//! a `#[ctor]` static initializer in a test binary.

use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use tempfile::TempDir;

/// What [`configure_test_binary_dispatch`] should do for the current process
/// invocation, as decided by the `classify` closure.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (so the process behaves as the aliased helper CLI) and
    /// return `None`. No aliases are installed.
    DispatchArg0Only,
    /// Do nothing and return `None`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install the arg0 dispatch aliases,
    /// restore the previous `CODEX_HOME`, and return a
    /// [`TestBinaryDispatchGuard`].
    InstallAliases,
}

/// Returned by [`configure_test_binary_dispatch`] when aliases are installed.
///
/// Holds the temporary `CODEX_HOME` directory and the arg0 path entry guard so
/// both remain alive for the lifetime of the test binary. Dropping the guard
/// tears down the temporary directory and releases the arg0 PATH entry.
pub struct TestBinaryDispatchGuard {
    // Retained so the temporary `CODEX_HOME` (which holds the installed
    // aliases) survives for as long as the guard is held.
    _codex_home: TempDir,
    path_entry: Arg0PathEntryGuard,
}

impl TestBinaryDispatchGuard {
    /// Paths to the helper executables installed by the arg0 dispatch aliases.
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.path_entry.paths()
    }
}

/// Reads `argv0` and `argv1`, asks `classify` how to handle this invocation,
/// and acts accordingly.
///
/// `classify` receives the current executable's file name (`argv0`'s basename)
/// and `argv1` (if present) and returns a [`TestBinaryDispatchMode`]:
///
/// * [`DispatchArg0Only`](TestBinaryDispatchMode::DispatchArg0Only) — dispatch
///   via arg0 and return `None`.
/// * [`Skip`](TestBinaryDispatchMode::Skip) — do nothing and return `None`.
/// * [`InstallAliases`](TestBinaryDispatchMode::InstallAliases) — set up a
///   temporary `CODEX_HOME` (prefixed with `codex_home_prefix`), install the
///   arg0 dispatch aliases under it, restore the previous `CODEX_HOME`, and
///   return `Some(TestBinaryDispatchGuard)`.
///
/// Intended to be called from a `#[ctor]` static initializer so it runs before
/// the test harness spawns any threads.
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("");
    let argv1 = args.next();

    match classify(exe_name, argv1.as_deref()) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            // Dispatch as the aliased helper CLI. For helper aliases this never
            // returns; for a normal invocation it installs the arg0 PATH entry
            // and returns a guard which we intentionally drop here since the
            // caller only wanted arg0 dispatch behavior.
            let _ = codex_arg0::arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => {
            let codex_home = tempfile::Builder::new()
                .prefix(codex_home_prefix)
                .tempdir()
                .ok()?;

            // Point `CODEX_HOME` at the temporary directory so the aliases are
            // installed there, then restore the previous value regardless of
            // whether installation succeeds.
            let previous_codex_home = std::env::var_os("CODEX_HOME");
            // Safety: called from a `#[ctor]` initializer before the test
            // harness spawns any threads, so mutating the environment is safe.
            unsafe {
                std::env::set_var("CODEX_HOME", codex_home.path());
            }

            let path_entry = codex_arg0::prepend_path_entry_for_codex_aliases();

            // Safety: still single-threaded (see above).
            unsafe {
                match previous_codex_home {
                    Some(value) => std::env::set_var("CODEX_HOME", value),
                    None => std::env::remove_var("CODEX_HOME"),
                }
            }

            let path_entry = path_entry.ok()?;
            Some(TestBinaryDispatchGuard {
                _codex_home: codex_home,
                path_entry,
            })
        }
    }
}
